('9c85480e-a212-5257-b118-1f9d0698df10'::uuid, 'Comprehensive Development Plan 2024-2030, Part 1: Ecological Profile 2022', 'plan', null, 'Vol. 1', 'City Planning and Development Office', null::date, 'City profile with hazard maps (flood, landslide, ground shaking, liquefaction, rain-induced landslide, storm surge) and the 2022 merger of the 28 district barangays into South, East and West, with District 29 renamed North (85 barangays).', array['A5.1','A5.3']::text[], 'https://drive.google.com/file/d/1PPGKRK_faECiOA1DGj1_qYCYZtwfU39o/view', 'Project Drive (CDRRMO folder)', 'current', 'standard', array[]::public.app_role[]),
