('c8f3dc4f-b3d3-57db-b472-73d62cbffdc8'::uuid, 'CDRRMC Resolution No. 03, s. 2025: support and adoption of Proclamation No. 920 (State of Calamity, Region VIII)', 'city_issuance', null, 'CDRRMC Res. No. 03, s. 2025', 'City DRRM Council', '2025-06-26'::date, 'Adopts the regional State of Calamity declared over the San Juanico Bridge load restriction. Example of how a national proclamation is read locally.', array['A1.6']::text[], 'https://drive.google.com/file/d/1s10x7KB-RfsTSm3gK7hhdnb-N5tgcra9/view', 'Project Drive (CDRRMO folder); scanned copy, text read by OCR', 'current', 'standard', array[]::public.app_role[]),
