('c2d8e175-0455-594b-8451-3d001a566c06'::uuid, 'Executive Order No. 2023-0026: creating the Project TRANSFORM Technical Working Group (DENR, EDC, NRC Adopt-a-City Program)', 'city_issuance', null, 'EO No. 2023-0026', 'Office of the City Mayor', '2023-03-24'::date, 'Five areas incl. GHG accounting for the LCCAP and disaster management (training, knowledge products); monitors the NRC resilience scorecard.', array['A10.2','A10.9','C3.1']::text[], 'https://drive.google.com/file/d/1gv1sw2ALK-lorRBnYh3HWHw3pZaKVZsH/view', 'Project Drive (CDRRMO folder); scanned copy, text read by OCR', 'current', 'standard', array[]::public.app_role[]),
